#include <string>
#include <stack>
#include <unordered_map>

class Solution {
public:
    /**
     * 使用堆疊檢查括號是否有效
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    bool isValid(std::string s) {
        // 建立堆疊
        std::stack<char> stack;

        // 建立右括號到左括號的映射
        std::unordered_map<char, char> mapping = {
            {')', '('},
            {'}', '{'},
            {']', '['}
        };

        // 遍歷字串
        for (char c : s) {
            // 如果是右括號
            if (mapping.count(c)) {
                // 檢查堆疊是否為空
                if (stack.empty()) {
                    return false;
                }

                // 取出堆疊頂部元素
                char top = stack.top();
                stack.pop();

                // 檢查是否匹配
                if (mapping[c] != top) {
                    return false;
                }
            } else {
                // 如果是左括號，push 到堆疊
                stack.push(c);
            }
        }

        // 檢查堆疊是否為空
        return stack.empty();
    }
};

