// 堆疊：遇到左括號就推入「對應的右括號」，遇到右括號就比對堆疊頂端
// 時間複雜度: O(n)，空間複雜度: O(n)
function isValid(s: string): boolean {
    const pairs: Record<string, string> = { '(': ')', '[': ']', '{': '}' };
    const stack: string[] = [];
    for (const ch of s) {
        if (ch in pairs) stack.push(pairs[ch]);
        else if (stack.pop() !== ch) return false;
    }
    return stack.length === 0;
}

