// 堆疊：遇到左括號就推入「對應的右括號」，遇到右括號就比對堆疊頂端
// 時間複雜度: O(n)，空間複雜度: O(n)
bool isValid(char* s) {
    int n = strlen(s);
    if (n % 2) return false;                      // 奇數長度不可能配對
    char* stack = malloc(n);
    int top = 0;
    bool ok = true;
    for (int i = 0; i < n && ok; i++) {
        char c = s[i];
        if (c == '(') stack[top++] = ')';
        else if (c == '[') stack[top++] = ']';
        else if (c == '{') stack[top++] = '}';
        else if (top == 0 || stack[--top] != c) ok = false;
    }
    ok = ok && top == 0;
    free(stack);
    return ok;
}

